def encode(s):
    if not s:
        return ""

    parts = []
    current = s[0]
    count = 1

    for char in s[1:]:
        if char == current:
            count += 1
        else:
            parts.append(current + (str(count) if count > 1 else ""))
            current = char
            count = 1

    parts.append(current + (str(count) if count > 1 else ""))
    return "".join(parts)


def decode(s):
    parts = []
    i = 0

    while i < len(s):
        char = s[i]
        i += 1
        start = i

        while i < len(s) and s[i].isdigit():
            i += 1

        count = int(s[start:i]) if i > start else 1
        parts.append(char * count)

    return "".join(parts)
